{
  "lecture": [
    {
      "etiquette": "F06",
      "R1": {
        "valeur": 1,
        "passage": "au moins deux fois moins de réécritures adoptées à tort que la règle \" garder si le score a monté \""
      },
      "R2": {
        "valeur": 1,
        "passage": "réécritures adoptées qui ne battent pas la consigne précédente sur des mondes frais (oracle) ; couverture des composantes plantées sur la famille jamais vue"
      },
      "R3": {
        "valeur": 1,
        "passage": "le vivier de conception (mondes plantés à graine scellée, jamais ceux du test)"
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 0,
        "motif": "La construction de l'e-processus, notamment les paris et la normalisation des différences de couverture, n'est pas spécifiée."
      },
      "R6": {
        "valeur": 0,
        "motif": "Un témoin est nommé, mais les journaux rejouables et les quelques mondes neufs ne donnent pas d'ordre de grandeur du coût en calcul, appels ou dollars."
      },
      "R7": {
        "valeur": 1,
        "passage": "la probabilité d'adopter une réécriture qui ne vaut pas mieux reste bornée au niveau choisi, même sous arrêt optionnel."
      },
      "N": {
        "valeur": "C7",
        "passage_fiche": "un e-processus par paris cumule la différence de couverture lue par l'oracle de ces mondes, et la réécriture est adoptée seulement quand la preuve accumulée devient décisive.",
        "passage_catalogue": "chaque candidate est comparée à la version en place **sur les mêmes instances**, et adoptée seulement quand un **e-processus par paris** accumule une preuve décisive"
      }
    },
    {
      "etiquette": "F07",
      "R1": {
        "valeur": 1,
        "passage": "à coût en dollars et en jetons strictement égal, le nombre de composantes plantées vraies couvertes au sens de l'oracle dans les retenues augmente d'au moins 25 %"
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle (nombre de composantes plantées vraies couvertes dans les propositions brutes et les retenues, nombre de lois fausses ou copies promues)"
      },
      "R3": {
        "valeur": 1,
        "passage": "chacun en session neuve sans historique, recevant exactement la même vue publique complète (sans aucun masquage de l'archive)"
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "fixer le plafond de jetons de sortie de chaque appel unitaire à floor((J - 5 * P * r) / 6), où r est le ratio tarifaire entre un jeton d'entrée et un jeton de sortie du modèle considéré."
      },
      "R6": {
        "valeur": 1,
        "passage": "sur 10 mondes plantés (quelques dizaines de dollars d'appels) et à comparer par l'oracle la couverture des 6 appels d'une carte contre 1 appel de 6 cartes à budget de dollars strictement égal."
      },
      "R7": {
        "valeur": 1,
        "passage": "Élimine à la source la corrélation autorégressive entre les six cartes d'un même proposeur au sein d'un appel, empêchant la première carte générée d'agir comme un attracteur pour les cinq suivantes."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F08",
      "R1": {
        "valeur": 1,
        "passage": "au moins 15 % de cartes en moins qui ne font que recopier l'existant, et au moins autant de composantes plantées couvertes, à coût égal"
      },
      "R2": {
        "valeur": 1,
        "passage": "composantes plantées couvertes (oracle) et copies promues ; témoin à coût égal : même génération sans filtre"
      },
      "R3": {
        "valeur": 0,
        "motif": "La fiche introduit un jugement de nouveauté par modèle dans la sélection des cartes et un filtre connecté au Web, sans nommer ni traiter les objections correspondantes."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 0,
        "motif": "Le critère de proximité bibliographique, les recherches à effectuer et la règle d'exclusion des cartes ne sont pas spécifiés."
      },
      "R6": {
        "valeur": 1,
        "passage": "quelques dollars de recherche et d'appels par génération"
      },
      "R7": {
        "valeur": 0,
        "motif": "Retirer les idées connues de la littérature n'implique ni moins de copies au sens de l'oracle ni le maintien de la couverture des composantes plantées."
      },
      "N": {
        "valeur": "C3",
        "passage_fiche": "Après la génération, un modèle relié à un moteur de recherche bibliographique et au Web écarte toute carte trop semblable à des travaux existants.",
        "passage_catalogue": "un **filtre de nouveauté** : un modèle relié à une recherche bibliographique (Semantic Scholar) et au Web écarte les idées trop proches de l'existant"
      }
    },
    {
      "etiquette": "F09",
      "R1": {
        "valeur": 1,
        "passage": "au moins 20 % de cartes promues par dollar en plus à la sixième génération qu'avec des parts égales"
      },
      "R2": {
        "valeur": 0,
        "motif": "La métrique est le nombre de promotions du juge statistique par dollar, et dépend donc explicitement de son verdict."
      },
      "R3": {
        "valeur": 0,
        "motif": "La répartition du budget entre proposeurs est pilotée par les promotions du juge statistique, contrairement à l'interdiction de sélectionner la composition sur ce verdict."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:composition"
      },
      "R5": {
        "valeur": 0,
        "motif": "La règle ne précise ni comment renormaliser les parts après application du plancher ni quoi faire lorsque tous les rendements sont nuls."
      },
      "R6": {
        "valeur": 0,
        "motif": "Le témoin à parts égales est nommé, mais la mention de journaux rejouables ne chiffre pas le coût de l'expérience décisive."
      },
      "R7": {
        "valeur": 0,
        "motif": "Dire que le budget va là où il rend le plus ne fournit pas de mécanisme établissant que le rendement passé persiste aux générations suivantes."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F10",
      "R1": {
        "valeur": 1,
        "passage": "le coût en dollars par génération diminue d'au moins 20 % par rapport à la course de référence"
      },
      "R2": {
        "valeur": 1,
        "passage": "coût en dollars par génération, relevé par les relais"
      },
      "R3": {
        "valeur": 1,
        "passage": "Le reste de l'organisme ne change pas : mêmes proposeurs, même juge, mêmes plafonds, même monde."
      },
      "R4": {
        "valeur": 0,
        "motif": "La fiche ne nomme aucune garantie restant démontrable après modification et ne précise pas le nul auquel elle s'applique."
      },
      "R5": {
        "valeur": 1,
        "passage": "Tripler le nombre m fixé d'avance pour la règle de Benjamini et Hochberg sur les valeurs e."
      },
      "R6": {
        "valeur": 1,
        "passage": "quelques dollars d'appels par graine"
      },
      "R7": {
        "valeur": 0,
        "motif": "La réaction supposée des proposeurs à la forme de leur vue ne relie pas un paramètre interne du juge à une baisse du coût des appels, dont les plafonds restent inchangés."
      },
      "N": {
        "valeur": "aucune"
      }
    }
  ]
}
